import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let xs = [1, 2, 3]
    let it = xs.iterator().map(|x| x * 2)
    let jt = xs.iterator().map(|x| x * 2)
    let a = it.any(|x| x > 4)
    if a { io.println("any-ok") } else { io.println("any-bad") }

    let n = jt.any(|x| x > 9)
    if n { io.println("any-miss-bad") } else { io.println("any-miss-ok") }

    return Ok(())
}
